 const incomingDates={last_inspection_month:row.last_month,next_inspection_month:row.next_month,...row.changes};
 const staleInspection=incomingDates.last_inspection_month&&inspection?.last_inspection_month&&incomingDates.last_inspection_month<inspection.last_inspection_month;
 if(row.completion_status!=='done'&&!staleInspection&&Object.entries(incomingDates).some(([key,value])=>key.endsWith('_month')&&value&&(!inspection?.[key]||value>inspection[key])))reasons.push('Incoming inspection is not explicitly marked done. Date updates are blocked; check the workbook completion status and preview again.');
