function reconConflict(row){if(Object.keys(row.changes||{}).some(key=>key.endsWith('_month'))&&row.completion_status!=='done')return true;if(!row.inspection_type)return true;const asset=reconAsset(row);if(row.confirmed&&Object.keys(row.changes||{}).length&&(!asset||asset.version!==row.version))return true;if(asset&&row.inspection_type==='Internal'&&!/tank|vessel/i.test(asset.family||''))return true;if(row.excluded)return false;if(Object.hasOwn(row,'next_month')&&asset&&!(row.ambiguous&&!row.confirmed)&&(row.confirmed||row.candidates?.length===1&&row.candidates[0].evidence.startsWith('Exact'))&&!Object.keys(reconMasterPreview({...row,changes:{}},asset,row.inspection_type).changes).length)return false;if(row.identifier&&row.description&&reconRows.some(other=>other!==row&&!other.excluded&&other.identifier&&other.description&&other.identifier.trim().toLowerCase()===row.identifier.trim().toLowerCase()&&other.description.trim().toLowerCase()===row.description.trim().toLowerCase()&&other.inspection_type===row.inspection_type))return true;if(row.chosen&&reconRows.some(other=>other!==row&&!other.excluded&&other.chosen===row.chosen&&other.inspection_type===row.inspection_type))return true;return row.ambiguous&&!row.confirmed}
