 const inspection=(asset.inspections||[]).find(i=>i.inspection_type===row.inspection_type&&applicable(i));
 const olderYear=row.last_date_role==='historical'&&/^\d{4}$/.test(row.last_original||'')&&inspection?.last_inspection_month&&row.last_original<=inspection.last_inspection_month.slice(0,4);
