function reconMissing(){const kind=$('#recon-type').value;let matched=new Set(reconRows.filter(r=>r.confirmed&&!r.excluded&&!reconConflict(r)).map(r=>r.chosen+'|'+r.inspection_type));return assets.filter(a=>active(a)&&reconScopedAsset(a)).flatMap(a=>(a.inspections||[]).filter(i=>applicable(i)&&(!kind||i.inspection_type===kind)&&!matched.has(a.id+'|'+i.inspection_type)).map(i=>({asset:a,inspection:i})))}
