 for(const r of reconRows){const a=reconAsset(r),changes=r.changes||{};rows.push([reconLabel(reconStatus(r)),r.row,r.identifier,r.description,r.inspection_type||'',r.planned_month||'',a?.id||r.chosen||'',a?.name||'',reconDue(r,a),(r.candidates||[]).map(c=>c.evidence).join('; '),!!r.confirmed,!!r.excluded,r.version??'',changes.last_inspection_month??'',changes.next_inspection_month??'',changes.service_status_original??'',changes.remark??'',r.last_month||'',r.remarks||'',r.final_remarks||'',r.progress||'',r.report||'',r.next_month||'',r.next_original||'',r.completion_status||'unknown',JSON.stringify(r.completion_evidence||[]),JSON.stringify(r.appliedOverrides||{}),JSON.stringify(r.appliedRemarks||[]),!!r.completed])}
