$('#recon-export').onclick=()=>{const missing=$('#recon-status').value==='missing'?reconMissing().filter(x=>`${x.asset.name} ${x.asset.id}`.toLowerCase().includes($('#recon-search').value.toLowerCase())):[];const rows=reconciliationExportRows(missing);const csv=rows.map(row=>row.map(v=>{let t=String(v??'');if(/^\s*[=+\-@]/.test(t))t="'"+t;return '"'+t.replaceAll('"','""')+'"'}).join(',')).join('\r\n'),url=URL.createObjectURL(new Blob(['\ufeff',csv],{type:'text/csv;charset=utf-8'})),link=el('a');link.href=url;link.download='reconciliation-complete-review.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};

