function selectedReconUpdates(){return reconRows.filter(r=>r.confirmed&&!r.excluded&&!r.completed&&r.changes&&Object.keys(r.changes).length).map(r=>({row:r,asset:reconAsset(r)}))}
function checkedReconUpdates(){return selectedReconUpdates().filter(({row})=>reconApplyChoices.get(row)===true)}
function updateReconApplyCount(){const count=checkedReconUpdates().length;$('#recon-apply-count').textContent=`${count} item${count===1?'':'s'} selected for application. Unchecked items stay in review.`;$('#recon-apply-confirm').disabled=count===0;$('#recon-apply-error').textContent=''}
$('#recon-review').onclick=()=>{const chosen=selectedReconUpdates();reconApplyChoices=new Map();const out=$('#recon-apply-list');out.replaceChildren(el('p','Choose which plan items to apply. A backup will be saved before the master is updated.'));const selectAll=el('button','Select all eligible updates','secondary');selectAll.type='button';selectAll.onclick=()=>{for(const check of out.querySelectorAll('input[type=checkbox]:not(:disabled)')){check.checked=true;check.onchange()}};out.append(selectAll);for(const {row,asset} of chosen){const box=el('div',null,'recon-detail-card'),label=el('label',null,'recon-apply-choice'),check=el('input');check.type='checkbox';const blocked=!asset||reconConflict(row);check.disabled=blocked;check.checked=false;check.setAttribute('aria-label',`Apply plan row ${row.row}: ${asset?assetDisplayName(asset):row.description||row.identifier||'Unavailable asset'}`);reconApplyChoices.set(row,check.checked);check.onchange=()=>{reconApplyChoices.set(row,check.checked);updateReconApplyCount()};label.append(check,el('strong',`${asset?assetDisplayName(asset)+' · '+asset.id:'Asset unavailable'} · ${row.inspection_type} · source row ${row.row}`));box.append(label);if(blocked)box.append(el('p',asset?'Resolve this item’s conflict before applying it.':'The matched master asset is no longer available.','error'));const inspection=(asset?.inspections||[]).find(i=>i.inspection_type===row.inspection_type);for(const [key,value] of Object.entries(row.changes)){const fieldLabel={last_inspection_month:'Last inspection month',next_inspection_month:'Next inspection month',service_status_original:'Service status',remark:'Add remark'}[key],old=key==='remark'?'New remark':key==='service_status_original'?asset?.[key]:inspection?.[key];box.append(el('p',`${fieldLabel}: ${old||'—'} → ${value}`))}out.append(box)}updateReconApplyCount();$('#recon-apply-dialog').showModal()};
$('#recon-view-updated').hidden=!Object.keys(recentReconUpdates).length;
$('#recon-view-updated').onclick=viewReconciledAssets;
$('#recon-view-confirmed').onclick=viewConfirmedReconAssets;
$('#recon-apply-close').onclick=()=>$('#recon-apply-dialog').close();
$('#recon-apply-confirm').onclick=async()=>{const selected=checkedReconUpdates();if(!selected.length||selected.some(({row,asset})=>!asset||reconConflict(row))){$('#recon-apply-error').textContent='Select at least one item without conflicts, then review it again.';return}const button=$('#recon-apply-confirm');button.disabled=true;try{const updates=selected.map(({row})=>({asset_id:row.chosen,version:row.version,inspection_type:row.inspection_type,fields:row.changes,source:{service_status:row.service_status,remarks:row.remarks,final_remarks:row.final_remarks,completion_evidence:row.completion_evidence,workbook:reconWorkbookName,sheet:row.source_sheet,row:row.row,identifier:row.identifier,scope:row.scope,last_original:row.last_original,next_original:row.next_original,planned_original:row.planned_original,progress:row.progress,report:row.report}}));const result=await api('/api/reconciliation/apply',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({updates})});recentReconUpdates=buildReconciliationHighlights(selected);try{sessionStorage.setItem('inspection-recon-highlights',JSON.stringify(recentReconUpdates))}catch{}$('#recon-view-updated').hidden=false;completeReconUpdates(selected,result.versions);persistReconciliation();$('#recon-apply-dialog').close();try{await load();renderRecon();message(`Updated ${result.updated} assets. Backup saved: ${result.backup}`)}catch(refreshError){message(`Updated ${result.updated} assets, but the display could not refresh. Reload the page. Backup saved: ${result.backup}`,true)}}catch(err){$('#recon-apply-error').textContent=err.message}finally{button.disabled=checkedReconUpdates().length===0}};

initialLoad.then(()=>{const saved=readReconciliation();if(!saved||!saved.rows.length)return;reconRows=saved.rows;reconWorkbookName=saved.name;reconSelectOptions();$('#recon-work').hidden=false;$('#recon-export').disabled=false;$('#recon-saved').textContent='Restored from this browser · '+reconWorkbookName;renderRecon()}).catch(()=>{});
